#!/usr/bin/python
# -*- coding: utf-8 -*-

import sys
PY2 = sys.version_info.major == 2

SETTING_MAP = {
    'rt_username': 'rutracker_login',
    'rt_password': 'rutracker_password',
    'rt_baseurl': 'rutracker_url',
    'rt_cookies': 'rutracker_cookies',
    'rt_flaresolverr_url': 'rutracker_flaresolverr_url',
    'rt_flaresolverr_timeout': 'rutracker_flaresolverr_timeout',
    'rt_flaresolverr_direct_timeout': 'rutracker_flaresolverr_direct_timeout',
}

class Settings(object):
    def get_setting(self, name):
        from xbmcaddon import Addon
        addon = Addon()
        mapped = SETTING_MAP.get(name, name)
        return addon.getSetting(mapped)

    def set_setting(self, name, value):
        from xbmcaddon import Addon
        addon = Addon()
        mapped = SETTING_MAP.get(name, name)
        addon.setSetting(mapped, value)

class Tracker:
    def __init__(self):
        self.settings = Settings()

    def Search(self, info):
        t = info['originaltitle']
        if PY2 and isinstance(t, str): 
            t = t.decode('utf8')

        Lout = []

        from vdlib.scrappers.rutracker import RuTrackerBase

        rutracker = RuTrackerBase(self.settings)

        for item in rutracker.search(t):

            Lout.append({
                "sids": item['seeds'],
                "size": item['size'],
                "title":item['title'],
                "url": item['dl_link']
            })
            pass

        return Lout

    def Query(self, query):
        try:
            return self.Search({'originaltitle': query})
        except Exception as e:
            print(e)
            return []

if __name__ == '__main__':
    print(Tracker().Query('ария'))
